class DisjointSet:
    def __init__(self, n):
        self.parentOrSize = [i for i in range(n)]
        self.size = [1]*(n+1)

    def find(self, x):
        if self.parentOrSize[x] != x:
            self.parentOrSize[x] = self.find(self.parentOrSize[x])
        return self.parentOrSize[x]

    def union_(self, a, b):
        asize = self.find(a)
        bsize = self.find(b)

        if asize == bsize:
            return

        if asize < bsize:
            self.parentOrSize[bsize] = asize
        else:
            self.parentOrSize[asize] = bsize
        self.size[bsize]+=self.size[asize]

