def solve(s: str) -> str:
    match = re.match(r"[^.]+*([^*.]+)*)?([^*.]*)$", s)
    if match and len(match.group(2)) == len(match.group(3)):
        return match.group(1).lower()+match.group(3).upper()
    else:
        raise ValueError("Input string is not a palindrome")

