    result = ''
    i = 0
    while i < len(s):
        if s[i].isdigit() or (i+1 < len(s) and s[i+1].isdigit()):
            num = int(s[:i])
            result += chr((ord('a') + num - 1) % 26 + 'a')
            i += 1
        elif not s[i].isalpha():
            if i != 0:
                next_char = s[i-1]
                num = ord(next_char) - ord('a') + 1
                result += chr((ord('a') + num - 1) % 26 + 'a')
                i += 1
        elif result == '':
            break
    return result

